//! Built-in, original, free Luminos skins and capes (generated by `tools/make-skins.mjs`; no Mojang art).
//! The first skin is the default every new offline account wears.

pub struct BuiltinSkin {
    pub id: &'static str,
    pub name: &'static str,
    pub blurb: &'static str,
    pub slim: bool,
    pub png: &'static [u8],
}

pub struct BuiltinCape {
    pub id: &'static str,
    pub name: &'static str,
    pub blurb: &'static str,
    pub png: &'static [u8],
}

